sourceCode['scroll-area-content.tsx'] = ''
  + 'import type { ComponentProps, FC } from "react";\n'
  + 'import { useCallback, useLayoutEffect, useRef } from "react";\n'
  + 'import { useStore } from "zustand";\n'
  + '\n'
  + 'import { useScrollAreaContext } from "./scroll-area-context";\n'
  + '\n'
  + 'type ScrollAreaContentProps = ComponentProps<"div"> & {\n'
  + '  children: React.ReactNode;\n'
  + '};\n'
  + '\n'
  + 'const ScrollAreaContent: FC<ScrollAreaContentProps> = (props) => {\n'
  + '  const { ref, children, ...rest } = props;\n'
  + '\n'
  + '  const contentRef = useRef<HTMLDivElement>(null);\n'
  + '\n'
  + '  const context = useScrollAreaContext();\n'
  + '\n'
  + '  const setContentHeight = useStore(context, (state) => state.setContentHeight);\n'
  + '  const setContentWidth = useStore(context, (state) => state.setContentWidth);\n'
  + '  useLayoutEffect(() => {\n'
  + '    const content = contentRef.current;\n'
  + '    if (!content) return;\n'
  + '\n'
  + '    // Observe content height & width changes.\n'
  + '    const resizeObserver = new ResizeObserver((entries) => {\n'
  + '      for (const entry of entries) {\n'
  + '        const height = entry.borderBoxSize[0].blockSize;\n'
  + '        setContentHeight(height);\n'
  + '        const width = entry.borderBoxSize[0].inlineSize;\n'
  + '        setContentWidth(width);\n'
  + '      }\n'
  + '    });\n'
  + '    resizeObserver.observe(content);\n'
  + '\n'
  + '    return () => {\n'
  + '      resizeObserver.unobserve(content);\n'
  + '    };\n'
  + '  }, [setContentHeight, setContentWidth]);\n'
  + '\n'
  + '  const setRef = useCallback(\n'
  + '    (el: HTMLDivElement) => {\n'
  + '      contentRef.current = el;\n'
  + '      if (typeof ref === "function") {\n'
  + '        ref(el);\n'
  + '      } else if (ref) {\n'
  + '        ref.current = el;\n'
  + '      }\n'
  + '    },\n'
  + '    [ref],\n'
  + '  );\n'
  + '\n'
  + '  return (\n'
  + '    <div ref={setRef} {...rest}>\n'
  + '      {children}\n'
  + '    </div>\n'
  + '  );\n'
  + '};\n'
  + '\n'
  + 'ScrollAreaContent.displayName = "ScrollArea.Content";\n'
  + '\n'
  + 'export { ScrollAreaContent };\n'
  ;

sourceCode['scroll-area-viewport.tsx'] = ''
  + 'import classNames from "classnames";\n'
  + 'import type { ComponentProps, FC } from "react";\n'
  + 'import { useLayoutEffect, useRef } from "react";\n'
  + 'import { useStore } from "zustand";\n'
  + '\n'
  + 'import { useScrollAreaContext } from "./scroll-area-context";\n'
  + 'import styles from "./scroll-area-viewport.module.css";\n'
  + '\n'
  + 'type ScrollAreaViewportProps = ComponentProps<"div">;\n'
  + '\n'
  + 'const ScrollAreaViewport: FC<ScrollAreaViewportProps> = (props) => {\n'
  + '  const { children, className, ...rest } = props;\n'
  + '\n'
  + '  const viewportRef = useRef<HTMLDivElement>(null);\n'
  + '\n'
  + '  const context = useScrollAreaContext();\n'
  + '\n'
  + '  const setViewportHeight = useStore(context, (s) => s.setViewportHeight);\n'
  + '  const setViewportWidth = useStore(context, (s) => s.setViewportWidth);\n'
  + '  const setScrollTop = useStore(context, (state) => state.setScrollTop);\n'
  + '  const setScrollLeft = useStore(context, (state) => state.setScrollLeft);\n'
  + '  const scrollTop = useStore(context, (state) => state.scrollTop);\n'
  + '  const scrollLeft = useStore(context, (state) => state.scrollLeft);\n'
  + '  const variant = useStore(context, (state) => state.variant);\n'
  + '\n'
  + '  // Handle scroll and resize events.\n'
  + '  useLayoutEffect(() => {\n'
  + '    const viewport = viewportRef.current;\n'
  + '    if (!viewport) return;\n'
  + '\n'
  + '    // Observe content height changes.\n'
  + '    const resizeObserver = new ResizeObserver((entries) => {\n'
  + '      for (const entry of entries) {\n'
  + '        const height = entry.borderBoxSize[0].blockSize;\n'
  + '        setViewportHeight(height);\n'
  + '        const width = entry.borderBoxSize[0].inlineSize;\n'
  + '        setViewportWidth(width);\n'
  + '      }\n'
  + '    });\n'
  + '    resizeObserver.observe(viewport);\n'
  + '\n'
  + '    // Listen to scroll events.\n'
  + '    const handleScroll = () => {\n'
  + '      if (!viewport) return;\n'
  + '      setScrollTop(viewport.scrollTop);\n'
  + '      setScrollLeft(viewport.scrollLeft);\n'
  + '    };\n'
  + '    viewport.addEventListener("scroll", handleScroll);\n'
  + '\n'
  + '    return () => {\n'
  + '      resizeObserver.unobserve(viewport);\n'
  + '      viewport.removeEventListener("scroll", handleScroll);\n'
  + '    };\n'
  + '  }, [setViewportHeight, setViewportWidth, setScrollTop, setScrollLeft]);\n'
  + '\n'
  + '  // Sync scrollTop & scrollLeft state with actual scroll position.\n'
  + '  useLayoutEffect(() => {\n'
  + '    const viewport = viewportRef.current;\n'
  + '    if (!viewport) return;\n'
  + '    if (Math.abs(viewport.scrollTop - scrollTop) > 1) {\n'
  + '      viewport.scrollTo({ top: scrollTop, behavior: "auto" });\n'
  + '    }\n'
  + '    if (Math.abs(viewport.scrollLeft - scrollLeft) > 1) {\n'
  + '      viewport.scrollTo({ left: scrollLeft, behavior: "auto" });\n'
  + '    }\n'
  + '  }, [scrollTop, scrollLeft]);\n'
  + '\n'
  + '  return (\n'
  + '    <div\n'
  + '      ref={viewportRef}\n'
  + '      className={classNames(className, styles.scrollAreaViewport)}\n'
  + '      data-variant={variant}\n'
  + '      {...rest}\n'
  + '    >\n'
  + '      {children}\n'
  + '    </div>\n'
  + '  );\n'
  + '};\n'
  + '\n'
  + 'ScrollAreaViewport.displayName = "ScrollArea.Viewport";\n'
  + '\n'
  + 'export { ScrollAreaViewport };\n'
  ;

